// ── 1. Pflichthelfer aus den Lib-Dateien laden ──────────────────────────────
const deviceStore  = global.get("deviceStore");
const timeHelpers  = global.get("timeHelpers");

if (!deviceStore || typeof deviceStore.ensureRuntime !== "function") {
    node.error("BOOT-FEHLER: deviceStore.ensureRuntime fehlt – /data/lib/device_store.js geladen?");
    return null;
}
if (!timeHelpers || typeof timeHelpers.nowIso !== "function") {
    node.error("BOOT-FEHLER: timeHelpers.nowIso fehlt – /data/lib/time_helpers.js geladen?");
    return null;
}

// ── 2. smarthome_runtime initialisieren (idempotent) ────────────────────────
// ensureRuntime gibt ein vorhandenes Runtime-Objekt zurück oder legt ein neues an.
// So bleibt der State bei einem Teil-Redeploy erhalten.
const now      = timeHelpers.nowIso();
const existing = global.get("smarthome_runtime");
const runtime  = deviceStore.ensureRuntime(existing, now);
global.set("smarthome_runtime", runtime);

// ── 3. flowHelpers registrieren ─────────────────────────────────────────────
// Gemeinsam genutzte Hilfsfunktionen, die in mehreren Flows benötigt werden.
// Zentral hier registrieren statt überall inline duplizieren.
global.set("flowHelpers", {

    /**
     * isEmptyPayload(payload)
     * Gibt true zurück, wenn der MQTT-Payload als leer gilt.
     * Leere Payloads kommen beim Löschen von retained Topics (MQTT Retained Clear).
     * Solche Nachrichten sollen nicht in den JSON-Parser oder die Handler gelangen.
     */
    isEmptyPayload(payload) {
        if (payload === undefined || payload === null) return true;
        if (Buffer.isBuffer(payload) && payload.length === 0) return true;
        if (typeof payload === "string" && payload.trim() === "") return true;
        return false;
    },

    /**
     * readPayloadObject(rawPayload)
     * Liest ein Payload sicher als JavaScript-Objekt.
     * Unterstützt: fertiges Objekt, JSON-String, Buffer mit JSON-Inhalt.
     * Gibt bei Fehler immer ein leeres Objekt {} zurück – nie null oder undefined.
     * Wird in Command- und Dashboard-Endpunkten genutzt, um den HTTP-Body zu lesen.
     */
    readPayloadObject(rawPayload) {
        // Schon ein Objekt – direkt zurückgeben (kein Buffer).
        if (rawPayload && typeof rawPayload === "object" && !Buffer.isBuffer(rawPayload)) {
            return rawPayload;
        }
        // Buffer zu UTF-8-String wandeln.
        if (Buffer.isBuffer(rawPayload)) {
            rawPayload = rawPayload.toString("utf8");
        }
        // JSON-String parsen.
        if (typeof rawPayload === "string") {
            const trimmed = rawPayload.trim();
            if (!trimmed) return {};
            try {
                const parsed = JSON.parse(trimmed);
                return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
            } catch (e) {
                return {};
            }
        }
        return {};
    }
});

// ── 4. Bootstatus melden ────────────────────────────────────────────────────
msg.payload = {
    status:        "bootstrapped",
    initialized_at: runtime.initialized_at,
    device_count:  Object.keys(runtime.devices || {}).length,
    master_count:  Object.keys(runtime.masters || {}).length
};
return msg;
